use bench_sandbox::parse_csv_line;
fn v(xs: &[&str]) -> Vec<String> { xs.iter().map(|s| s.to_string()).collect() }
#[test] fn plain() { assert_eq!(parse_csv_line("a,b,c"), v(&["a","b","c"])); }
#[test] fn empty_fields() { assert_eq!(parse_csv_line("a,,c"), v(&["a","","c"])); }
#[test] fn trailing_empty() { assert_eq!(parse_csv_line("a,"), v(&["a",""])); }
#[test] fn comma_in_quotes() { assert_eq!(parse_csv_line("a,\"b,c\",d"), v(&["a","b,c","d"])); }
#[test] fn escaped_quotes() { assert_eq!(parse_csv_line("\"a\"\"b\""), v(&["a\"b"])); }
#[test] fn quoted_whole() { assert_eq!(parse_csv_line("\"hello, world\""), v(&["hello, world"])); }
